'use client';

import React, { useState, useMemo } from 'react';
import { AutoChart, Chart } from '@vizora/react';
import { recommendChartSpec } from '@vizora/intelligence';
import { ChartType } from '@vizora/core';
import { CompassDial } from '../components/CompassDial';
import { LegendBand } from '../components/LegendBand';
import { CartoButton } from '../components/CartoButton';

interface PresetItem {
  name: string;
  type: ChartType;
  x: string;
  y?: string;
  data: Record<string, unknown>[];
  profile: string;
}

// Preset Geodetic Datasets
const PRESETS: Record<string, PresetItem> = {
  sales: {
    name: 'Regional Sales Survey',
    type: 'bar',
    x: 'region',
    y: 'sales',
    profile: 'categorical [region] + quantitative [sales]',
    data: [
      { region: 'North America', sales: 1250 },
      { region: 'Europe', sales: 980 },
      { region: 'Asia Pacific', sales: 1420 },
      { region: 'Latin America', sales: 610 },
      { region: 'Middle East', sales: 430 },
    ],
  },
  trend: {
    name: 'MRR Growth Traverse',
    type: 'line',
    x: 'date',
    y: 'mrr',
    profile: 'temporal [date] + quantitative [mrr]',
    data: [
      { date: '2026-01-01', mrr: 12400 },
      { date: '2026-02-01', mrr: 15800 },
      { date: '2026-03-01', mrr: 19200 },
      { date: '2026-04-01', mrr: 24500 },
      { date: '2026-05-01', mrr: 31000 },
      { date: '2026-06-01', mrr: 38200 },
    ],
  },
  scatter: {
    name: 'Geodetic Coordinate Scatter',
    type: 'scatter',
    x: 'height',
    y: 'weight',
    profile: 'quantitative [height] + quantitative [weight]',
    data: [
      { height: 160, weight: 55 },
      { height: 165, weight: 62 },
      { height: 172, weight: 68 },
      { height: 178, weight: 74 },
      { height: 185, weight: 82 },
      { height: 190, weight: 91 },
    ],
  },
  histogram: {
    name: 'Customer Elevation Profile',
    type: 'histogram',
    x: 'age',
    y: 'count',
    profile: 'quantitative distribution [age]',
    data: [
      { age: 19 }, { age: 22 }, { age: 24 }, { age: 25 }, { age: 28 },
      { age: 29 }, { age: 31 }, { age: 34 }, { age: 35 }, { age: 38 },
      { age: 41 }, { age: 44 }, { age: 47 }, { age: 52 }, { age: 58 },
    ],
  },
  kpi: {
    name: 'ARR Geodetic Baseline',
    type: 'kpi-sparkline',
    x: 'month',
    y: 'arr',
    profile: 'single target + sparkline trend',
    data: [
      { month: 'Jan', arr: 450000 },
      { month: 'Feb', arr: 520000 },
      { month: 'Mar', arr: 610000 },
      { month: 'Apr', arr: 740000 },
      { month: 'May', arr: 890000 },
      { month: 'Jun', arr: 1200000 },
    ],
  },
};

export default function Home() {
  const [activePresetKey, setActivePresetKey] = useState<keyof typeof PRESETS>('sales');
  const [selectedChartType, setSelectedChartType] = useState<ChartType>('bar');
  const [orientation, setOrientation] = useState<'vertical' | 'horizontal'>('vertical');
  const [mode, setMode] = useState<'auto' | 'explicit'>('auto');
  const [customJson, setCustomJson] = useState<string>('');
  const [copied, setCopied] = useState<boolean>(false);

  const currentPreset = PRESETS[activePresetKey];

  // Live parsed data array
  const currentData = useMemo(() => {
    if (!customJson.trim()) return currentPreset.data;
    try {
      const parsed = JSON.parse(customJson);
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    } catch {
      // Invalid JSON fallback
    }
    return currentPreset.data;
  }, [customJson, currentPreset.data]);

  // Recommended spec from intelligence package
  const autoSpec = useMemo(() => {
    const rec = recommendChartSpec(currentData);
    rec.title = `${currentPreset.name} (AutoChart)`;
    return rec;
  }, [currentData, currentPreset.name]);

  // Active computed spec
  const computedSpec = useMemo(() => {
    if (mode === 'auto') return autoSpec;

    return {
      version: '0.1.0' as const,
      type: selectedChartType,
      title: `${currentPreset.name} (Explicit)`,
      data: currentData,
      encoding: {
        x: currentPreset.x ? { field: currentPreset.x } : undefined,
        y: currentPreset.y ? { field: currentPreset.y } : undefined,
        orientation: selectedChartType === 'bar' ? orientation : undefined,
      },
      config: { width: 600, height: 380 },
    };
  }, [mode, autoSpec, selectedChartType, currentPreset, currentData, orientation]);

  // Handle Preset Select
  const handleSelectPreset = (key: keyof typeof PRESETS) => {
    setActivePresetKey(key);
    setSelectedChartType(PRESETS[key].type);
    setCustomJson('');
  };

  const handleCopySpec = () => {
    navigator.clipboard.writeText(JSON.stringify(computedSpec, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Find max value item for Flag Pin Anomaly callout
  const maxItem = useMemo(() => {
    if (!currentData || currentData.length === 0) return null;
    const yKey = currentPreset.y || currentPreset.x;
    let maxVal = -Infinity;
    let item: Record<string, unknown> | null = null;
    currentData.forEach((d) => {
      const val = Number(d[yKey] ?? 0);
      if (!isNaN(val) && val > maxVal) {
        maxVal = val;
        item = d;
      }
    });
    return { key: yKey, val: maxVal, item };
  }, [currentData, currentPreset]);

  return (
    <div className="min-h-screen bg-[#ecefea] text-[#1e2a22] p-4 md:p-8 carto-grid-bg">
      {/* Title Block / Header */}
      <header className="max-w-7xl mx-auto mb-8 carto-panel p-6 bg-[#f7faf5]">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-[#1e2a22] pb-4">
          <div>
            <div className="font-data-spec text-[#6e756a] text-xs mb-1">
              SURVEY NO. 1894 // INSTRUMENTAL MINIMALISM // CHART RUNTIME
            </div>
            <h1 className="font-display-hero text-3xl md:text-4xl text-[#1e2a22] tracking-tight">
              Vizora : Cartography of Data
            </h1>
            <p className="font-body-ui text-[#434844] text-sm mt-1 max-w-2xl">
              Framework-agnostic chart runtime + deterministic data profiling + automatic chart recommendation.
              Rendering pure SVG scene graphs derived from validated <code className="font-data-spec bg-[#dee5d7] px-1 border border-[#1e2a22]">ChartSpec</code> contracts.
            </p>
          </div>

          <div className="flex flex-col items-end gap-1.5 font-data-spec text-xs text-[#6e756a]">
            <div className="px-2.5 py-1 bg-[#dee5d7] border border-[#1e2a22] text-[#1e2a22] font-semibold flex items-center gap-2">
              <span className="h-2 w-2 bg-[#c2872e]" />
              lat : 45.0n / lon : 93.2w
            </div>
            <div>datum : geodetic-1894 / engine : svg-ssr</div>
          </div>
        </div>
      </header>

      {/* Main 12-Column Grid Workspace */}
      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        
        {/* Left Column (5 Cols): Controls & Compass Recommendation Dial */}
        <div className="lg:col-span-5 space-y-6">
          
          {/* Engine Mode Switcher */}
          <div className="carto-panel p-4 space-y-3">
            <div className="flex items-center justify-between border-b border-[#1e2a22] pb-2">
              <span className="font-label-caps text-[#1e2a22]">Execution Mode</span>
              <span className="font-data-spec text-[#6e756a] text-xs">mode : {mode}</span>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => setMode('auto')}
                className={`py-2 px-3 border text-xs font-mono transition-all text-center ${
                  mode === 'auto'
                    ? 'bg-[#c2872e] text-[#1e2a22] border-[#1e2a22] font-bold'
                    : 'bg-[#f7faf5] text-[#6e756a] border-[#6e756a]/30 hover:border-[#1e2a22]'
                }`}
              >
                AutoChart (Heuristic)
              </button>
              <button
                onClick={() => setMode('explicit')}
                className={`py-2 px-3 border text-xs font-mono transition-all text-center ${
                  mode === 'explicit'
                    ? 'bg-[#c2872e] text-[#1e2a22] border-[#1e2a22] font-bold'
                    : 'bg-[#f7faf5] text-[#6e756a] border-[#6e756a]/30 hover:border-[#1e2a22]'
                }`}
              >
                Explicit &lt;Chart /&gt;
              </button>
            </div>
          </div>

          {/* The Compass Recommendation Dial */}
          <CompassDial
            recommendedType={autoSpec.type}
            selectedType={mode === 'auto' ? autoSpec.type : selectedChartType}
            onSelectType={(type) => {
              setSelectedChartType(type);
              setMode('explicit');
            }}
            confidence={0.96}
            dataSummary={currentPreset.profile}
          />

          {/* Preset Datasets Selection */}
          <div className="carto-panel p-4 space-y-3">
            <div className="flex items-center justify-between border-b border-[#1e2a22] pb-2">
              <span className="font-label-caps text-[#1e2a22]">Sample Geodetic Datasets</span>
              <span className="font-data-spec text-[#6e756a] text-xs">n = {Object.keys(PRESETS).length}</span>
            </div>

            <div className="grid grid-cols-1 gap-1.5">
              {(Object.keys(PRESETS) as Array<keyof typeof PRESETS>).map((key) => {
                const preset = PRESETS[key];
                const isActive = activePresetKey === key;
                return (
                  <button
                    key={key}
                    onClick={() => handleSelectPreset(key)}
                    className={`px-3 py-2 border text-left text-xs font-mono flex items-center justify-between transition-all ${
                      isActive
                        ? 'bg-[#1e2a22] text-[#f7faf5] border-[#1e2a22]'
                        : 'bg-[#f7faf5] text-[#1e2a22] border-[#6e756a]/30 hover:border-[#1e2a22]'
                    }`}
                  >
                    <span>{preset.name}</span>
                    <span className="text-[10px] opacity-75">[{preset.type}]</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Explicit Controls (If Mode === explicit) */}
          {mode === 'explicit' && (
            <div className="carto-panel p-4 space-y-3 bg-[#dee5d7]">
              <div className="font-label-caps text-[#1e2a22] border-b border-[#1e2a22] pb-2">
                Explicit Encoding Controls
              </div>

              <div className="flex items-center justify-between text-xs font-mono">
                <span className="text-[#6e756a]">Chart Type:</span>
                <select
                  value={selectedChartType}
                  onChange={(e) => setSelectedChartType(e.target.value as ChartType)}
                  className="bg-[#f7faf5] border border-[#1e2a22] px-2 py-1 text-[#1e2a22] outline-none"
                >
                  <option value="bar">Bar Survey</option>
                  <option value="line">Temporal Line</option>
                  <option value="scatter">Scatter Plot</option>
                  <option value="histogram">Histogram</option>
                  <option value="kpi-sparkline">KPI Sparkline</option>
                </select>
              </div>

              {selectedChartType === 'bar' && (
                <div className="flex items-center justify-between text-xs font-mono pt-2 border-t border-[#1e2a22]/30">
                  <span className="text-[#6e756a]">Bar Orientation:</span>
                  <CartoButton
                    variant="secondary"
                    onClick={() => setOrientation(orientation === 'vertical' ? 'horizontal' : 'vertical')}
                  >
                    {orientation === 'vertical' ? 'Vertical [↕]' : 'Horizontal [↔]'}
                  </CartoButton>
                </div>
              )}
            </div>
          )}

          {/* Raw JSON Data Input Drawer */}
          <div className="carto-panel p-4 space-y-2">
            <div className="flex items-center justify-between border-b border-[#1e2a22] pb-2">
              <span className="font-label-caps text-[#1e2a22]">Raw JSON Data Input</span>
              {customJson && (
                <button
                  onClick={() => setCustomJson('')}
                  className="font-data-spec text-[#d6502b] hover:underline"
                >
                  reset
                </button>
              )}
            </div>
            <textarea
              rows={4}
              value={customJson}
              onChange={(e) => setCustomJson(e.target.value)}
              placeholder={`Paste tabular JSON array:\n[{"region": "US", "sales": 100}, {"region": "EU", "sales": 80}]`}
              className="w-full bg-[#f7faf5] border border-[#6e756a] p-2.5 font-data-spec text-xs text-[#1e2a22] outline-none focus:border-[#c2872e]"
            />
          </div>
        </div>

        {/* Right Column (7 Cols): SVG Render Instrument & ChartSpec Readout */}
        <div className="lg:col-span-7 space-y-6">
          
          {/* Main Chart Instrument Panel */}
          <div className="carto-panel bg-[#f7faf5]">
            
            {/* Instrument Header */}
            <div className="p-4 border-b border-[#1e2a22] flex items-center justify-between bg-[#ecefea]">
              <div>
                <div className="font-data-spec text-xs text-[#6e756a]">
                  {mode === 'auto' ? `autochart : inferred [${computedSpec.type}]` : `explicit : bound [x=${currentPreset.x}, y=${currentPreset.y || ''}]`}
                </div>
                <h2 className="font-headline-md text-lg text-[#1e2a22]">
                  {currentPreset.name}
                </h2>
              </div>

              <div className="px-3 py-1 bg-[#c2872e] text-[#1e2a22] border border-[#1e2a22] font-label-caps text-[10px]">
                Determinism Verified
              </div>
            </div>

            {/* SVG Render Container */}
            <div className="p-6 bg-[#f7faf5] flex justify-center items-center min-h-[400px]">
              {mode === 'auto' ? (
                <AutoChart data={currentData} title={`${currentPreset.name}`} />
              ) : (
                <Chart
                  data={currentData}
                  type={selectedChartType}
                  x={currentPreset.x}
                  y={currentPreset.y}
                  orientation={orientation}
                  title={`${currentPreset.name}`}
                />
              )}
            </div>

            {/* Signature Legend Band directly below chart canvas */}
            <LegendBand spec={computedSpec} dataCount={currentData.length} />
          </div>

          {/* Flag Pin Anomaly Callout Card */}
          {maxItem && (
            <div className="carto-panel p-4 bg-[#dee5d7] flex items-center justify-between border-l-4 border-l-[#d6502b]">
              <div className="flex items-center gap-3">
                <div className="w-3 h-3 bg-[#d6502b]" />
                <div>
                  <div className="font-label-caps text-[#d6502b]">Flag Pin Anomaly Detected</div>
                  <div className="font-data-spec text-xs text-[#1e2a22]">
                    max datum point : {String(maxItem.item?.[currentPreset.x] || maxItem.item?.[currentPreset.y || ''])} = {maxItem.val}
                  </div>
                </div>
              </div>
              <span className="font-data-spec text-xs text-[#6e756a]">status : flag-pin-active</span>
            </div>
          )}

          {/* Validated ChartSpec Contract JSON */}
          <div className="carto-panel p-4 space-y-3">
            <div className="flex items-center justify-between border-b border-[#1e2a22] pb-2">
              <div>
                <span className="font-label-caps text-[#1e2a22]">ChartSpec JSON Contract</span>
                <span className="font-data-spec text-[#6e756a] text-xs block">zod runtime validated IR</span>
              </div>

              <CartoButton variant="secondary" onClick={handleCopySpec}>
                {copied ? '✓ Copied' : 'Copy Spec JSON'}
              </CartoButton>
            </div>

            <pre className="bg-[#1e2a22] text-[#ecefea] p-4 font-data-spec text-xs overflow-x-auto max-h-[320px] border border-[#1e2a22]">
              {JSON.stringify(computedSpec, null, 2)}
            </pre>
          </div>

          {/* Integration Snippet */}
          <div className="carto-panel p-4 space-y-2 bg-[#f7faf5]">
            <span className="font-label-caps text-[#1e2a22]">React Integration (&lt; 4 Lines)</span>
            <pre className="bg-[#ecefea] p-3 border border-[#1e2a22] font-data-spec text-xs text-[#1e2a22]">
{mode === 'auto'
  ? `import { AutoChart } from '@vizora/react';\n\n<AutoChart data={data} />`
  : `import { Chart } from '@vizora/react';\n\n<Chart data={data} type="${selectedChartType}" x="${currentPreset.x}" y="${currentPreset.y || ''}" />`}
            </pre>
          </div>
        </div>
      </main>
    </div>
  );
}
